export async function serveFake({db,dir,keys,website}){
 if(await qaGuard(db)!==dir)refused();await qaPrivatePath(dir);const protocol=await createFakeProtocol({db,keys,website});
 const sockets=new Set(),servers=[];let chain=Promise.resolve();
 const serial=fn=>{const next=chain.then(fn);chain=next.catch(()=>{});return next;};
 try{for(const kind of ['control','frames']){
  const path=dir+'/'+kind+'.sock'; // Refuse existing paths; never unlink another process's socket.
  try{await lstat(path);throw Error('QA_ONLY: socket exists; stop its owner first');}catch(e){if(e.code!=='ENOENT')throw e;}
  const server=createServer(socket=>{if(sockets.size>=8)return socket.destroy();sockets.add(socket);let timer;socket.setTimeout(75000,()=>socket.destroy());socket.on('error',()=>{});socket.on('close',()=>{sockets.delete(socket);clearInterval(timer);});
   socket.on('data',frameReader(value=>{void serial(async()=>{try{if(kind==='control')socket.end(encodeFrame(await protocol.rpc(value)));else{let seq=0;const send=async()=>{try{const frame=await protocol.frame(value,seq++);if(frame&&!socket.destroyed&&socket.writableLength===0)socket.write(frame);}catch{socket.destroy();}};await send();if(!socket.destroyed)timer=setInterval(()=>void serial(send),1000);}}catch{socket.destroy();}});},()=>socket.destroy()));
  });servers.push(server);await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(path,resolve);});await chmod(path,0o600);
 }}catch(e){for(const s of sockets)s.destroy();for(const s of servers)if(s.listening)await new Promise(r=>s.close(r));throw e;}
 return {close:async()=>{for(const s of sockets)s.destroy();for(const s of servers)await new Promise(r=>s.close(r));await chain;}};
}
export async function loadQaKeys(dir){const keys={};for(const [kind,env] of Object.entries({request:'SJC_BROWSER_WEB_RPC_KEY',response:'SJC_BROWSER_WEB_RESPONSE_KEY',frame:'SJC_BROWSER_FRAME_KEY'})){const file=dir+'/keys/'+kind+'.hex';await qaPrivatePath(file,{file:true});const text=(await readFile(file,'utf8')).trim();if(!/^[a-f0-9]{64}$/.test(text))refused();if(process.env[env]!==text)refused();keys[kind]=Buffer.from(text,'hex');}if(new Set(Object.values(keys).map(b=>b.toString('hex'))).size!==3)refused();return keys;}
